package io.github.diodeme.ji.artifact;

/** Full authorization scope for an artifact reference. */
public record ArtifactScope(String hostId, String workspaceId, String sessionId) {
    public ArtifactScope {
        require(hostId, "hostId");
        require(workspaceId, "workspaceId");
        require(sessionId, "sessionId");
    }

    private static void require(String value, String name) {
        if (value == null || value.isBlank()) throw new IllegalArgumentException(name + " must not be blank");
    }
}
